public class Element_hasClass_TriageGen2Test {

    @Test
    public void testHasClassNull() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        // when
        boolean result = element.hasClass(null);
        // then
        assertFalse(result);
    }

    @Test
    public void testHasClassEmptyString() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        // when
        boolean result = element.hasClass("");
        // then
        assertFalse(result);
    }

    @Test
    public void testHasClassMatch() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        // when
        boolean result = element.hasClass("class");
        // then
        assertTrue(result);
    }

    @Test
    public void testHasClassNoMatch() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        // when
        boolean result = element.hasClass("otherClass");
        // then
        assertFalse(result);
    }

    @Test
    public void testHasClassMatchWhitespace() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        element.attr("class", " class ");
        // when
        boolean result = element.hasClass("class");
        // then
        assertTrue(result);
    }

    @Test
    public void testHasClassNoMatchWhitespace() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        element.attr("class", " otherClass ");
        // when
        boolean result = element.hasClass("class");
        // then
        assertFalse(result);
    }

    @Test
    public void testHasClassMatchCaseInsensitive() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        element.attr("class", "CLASS");
        // when
        boolean result = element.hasClass("class");
        // then
        assertTrue(result);
    }

    @Test
    public void testHasClassNoMatchCaseInsensitive() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        element.attr("class", "OTHERCLASS");
        // when
        boolean result = element.hasClass("class");
        // then
        assertFalse(result);
    }

    @Test
    public void testHasClassMultipleClasses() {
        // given
        Element element = new Element(Tag.valueOf("div"), "", null);
        element.attr("class", "class otherClass");
        // when
        boolean result = element.hasClass("class");
        // then
        assertTrue(result);
    }
}
